:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --text: #f4f4f4;
  --accent: #41a6f6;
  --correct: #38b764;
  --wrong: #b13e53;
  --font: "Courier New", Courier, monospace;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  image-rendering: pixelated;
}

.card {
  width: 100%;
  max-width: 420px;
  padding: 24px;
  background: var(--card);
  border: 4px solid var(--text);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  margin: 0 0 16px;
  font-size: 20px;
  letter-spacing: 2px;
  text-transform: uppercase;
}

.question {
  margin: 0 0 24px;
  font-size: 28px;
  font-weight: bold;
  min-height: 42px;
}

.answers {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 16px;
  text-align: left;
}

.answer-label {
  font-size: 14px;
  letter-spacing: 1px;
  text-transform: uppercase;
  opacity: 0.8;
}

.btn {
  font-family: var(--font);
  font-size: 18px;
  font-weight: bold;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--text);
  padding: 12px 16px;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-height: 48px;
}

.btn:hover { background: var(--accent); color: var(--bg); }
.btn:focus-visible { outline: 4px solid var(--accent); outline-offset: 2px; }
.btn:active { transform: translate(2px, 2px); }
.btn:disabled { cursor: not-allowed; opacity: 0.6; }

.answer.correct { background: var(--correct); color: var(--bg); border-color: var(--correct); }
.answer.wrong { background: var(--wrong); color: var(--text); border-color: var(--wrong); }

.score-line {
  margin: 0 0 16px;
  font-size: 18px;
}

#score { font-weight: bold; color: var(--accent); }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.controls .btn { flex: 1; }

@media (max-width: 360px) {
  .card { padding: 16px; }
  .question { font-size: 24px; }
  .answers { grid-template-columns: 1fr; }
  .controls { flex-direction: column; }
}

(function () {
  'use strict';

  var questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  var state = { index: 0, answered: false, score: 0 };

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  function render() {
    var q = questions[state.index];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    scoreEl.textContent = String(state.score);
    answerA.disabled = state.answered;
    answerB.disabled = state.answered;
    answerA.classList.remove('correct', 'wrong');
    answerB.classList.remove('correct', 'wrong');
  }

  function lockAnswers() {
    state.answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
  }

  function handleAnswer(choice) {
    if (state.answered) return;
    var q = questions[state.index];
    lockAnswers();
    if (choice === q.correct) {
      state.score += 1;
      (choice === 'a' ? answerA : answerB).classList.add('correct');
    } else {
      (choice === 'a' ? answerA : answerB).classList.add('wrong');
      (q.correct === 'a' ? answerA : answerB).classList.add('correct');
    }
    scoreEl.textContent = String(state.score);
  }

  answerA.addEventListener('click', function () { handleAnswer('a'); });
  answerB.addEventListener('click', function () { handleAnswer('b'); });

  nextBtn.addEventListener('click', function () {
    if (!state.answered) return;
    if (state.index < questions.length - 1) {
      state.index += 1;
      state.answered = false;
      render();
    } else {
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      answerA.classList.remove('correct', 'wrong');
      answerB.classList.remove('correct', 'wrong');
    }
  });

  restartBtn.addEventListener('click', function () {
    state.index = 0;
    state.answered = false;
    state.score = 0;
    render();
  });

  render();
})();
